fn raw_string() -> TestResult {
    run_test(r#"r#'abcde""fghi"''''jkl'#"#, r#"abcde""fghi"''''jkl"#)?;
    run_test(r#"r##'abcde""fghi"''''#jkl'##"#, r#"abcde""fghi"''''#jkl"#)?;
    run_test(
        r#"r###'abcde""fghi"'''##'#jkl'###"#,
        r#"abcde""fghi"'''##'#jkl"#,
    )?;
    run_test("r#''#", "")?;
    run_test(
        r#"r#'a string with sharp inside # and ends with #'#"#,
        "a string with sharp inside # and ends with #",
    )
}

